// Shared by the page and the service worker: formatting of reasons, events and push texts.
self.MS_FMT = (function () {
  const I = self.MS_I18N;
  const fill = (s, p) => String(s).replace(/\{(\w+)\}/g, (m, k) => (p && p[k] != null ? p[k] : ''));
  const num = (lang, x, d) => new Intl.NumberFormat(I[lang].locale, {maximumFractionDigits: d || 0, minimumFractionDigits: d || 0}).format(x);
  const pct = (lang, x, d) => (lang === 'en' ? num(lang, x, d) + '%' : num(lang, x, d) + ' %');
  function bytes(lang, b) { b = +b || 0; let i = 0; const u = I[lang].units; while (b >= 1024 && i < u.length - 1) { b /= 1024; i++; } return num(lang, b, b < 10 && i > 0 ? 1 : 0) + ' ' + u[i]; }
  function reason(lang, r, extra) {
    r = r || {k: 'ok'}; const tr = I[lang].r[r.k];
    return tr ? fill(tr, Object.assign({ago: '–', next: '–'}, r, extra || {})) : '';
  }
  // a push payload from the agent -> {title, body, tag, critical, view}
  function pushText(lang, m) {
    const T = I[lang], P = T.pn, d = m.data || {}, name = T.names[m.svc] || m.svc || T.brand;
    if (m.type === 'test') return {title: P.testT, body: P.testB, tag: 'test'};
    if (m.type === 'weekly') return {title: P.weeklyT, tag: 'weekly', view: 'res',
      body: fill(P.weeklyB, {u: d.uptime == null ? '–' : pct(lang, d.uptime, d.uptime >= 99.95 ? 0 : 2), f: d.fails || 0, t: bytes(lang, d.traffic || 0), d: d.disk == null ? '–' : pct(lang, d.disk)})};
    if (d.k === 'svc') {
      if (d.state === 'ok') return {title: fill(T.ev.back, {name}), body: reason(lang, d.r), tag: 'svc-' + m.svc};
      return {title: fill(d.state === 'down' ? P.svcDown : P.svcWarn, {name}), body: reason(lang, d.r), tag: 'svc-' + m.svc};
    }
    if (d.k === 'weekly') return pushText(lang, Object.assign({}, m, {type: 'weekly'}));
    if (T.ev[d.k]) return {title: fill(T.ev[d.k], Object.assign({}, d, {pct: d.pct != null ? num(lang, d.pct, d.pct % 1 ? 1 : 0) : ''})), body: '', tag: d.k};
    return {title: T.brand, body: m.text || '', tag: 'misc'};
  }
  return {fill, num, pct, bytes, reason, pushText};
})();
